// COPY of northlight-dispatcher/dashboard/lib/blog-checks.js. The dispatcher copy is the source:
// change it there (with its tests) and copy it here, do not edit this file on its own.
// Used by .github/scripts/blog-checks/run.js (the "Blog checks" workflow). No dependencies.
//
// lib/blog-checks.js — deterministic quality checks for a blog post, no network and no model.
//
// This is Elizabeth's /blog-pre-publish checklist as code, aligned to what the site template
// (bynorthlight-site/_layouts/post.html) really writes, not to the older checklist wording:
//   - og:site_name is "Northlight Advisory Services" (the checklist said "Northlight")
//   - the Article schema author url is https://bynorthlight.ca/about (the checklist said /about.html)
//   - the browser title always ends " — Northlight Advisory Services" (31 characters), so a total of
//     60 is not reachable with a real headline; the limit is applied to the part we write
//   - the author tag, canonical, OG image and Twitter tags are written by the layout, so on the
//     markdown they cannot fail; they are checked on the live HTML instead
// Three inputs: checkMarkdown() (the post file we are about to commit), checkHtml() (the live page)
// and diffPolish() (blog polish output against what it was given). Each returns plain data;
// blog-gate.js decides what blocks and what is fixed.
//
// No dependencies on the rest of the dispatcher, so the site repo can copy this file for its own CI.

const SITE         = 'https://bynorthlight.ca';
const SITE_NAME    = 'Northlight Advisory Services';
const TITLE_SUFFIX = ` — ${SITE_NAME}`;
const OG_IMAGE     = `${SITE}/northlight-og-image.png`;
const AUTHOR       = 'Elizabeth Lemoine';
const AUTHOR_URL   = `${SITE}/about`;

const SOURCE_LABELS = ['Blog · Essay', 'Blog · Guide', 'Blog · Review', 'Northlight · About', 'Aurora Brief · Essay'];
const DESC_MIN = 120, DESC_MAX = 155;
const TITLE_PASS = 60;   // the part we write (without the suffix)
const TITLE_FAIL = 75;

const check = (id, label, status, note = '', extra = {}) => ({ id, label, status, note, ...extra });
const pass = (id, label, note) => check(id, label, 'pass', note);
const fail = (id, label, note, extra) => check(id, label, 'fail', note, extra);
const warn = (id, label, note, extra) => check(id, label, 'warn', note, extra);
const na   = (id, label, note) => check(id, label, 'na', note);

const decode = s => String(s == null ? '' : s)
  .replace(/&quot;/g, '"').replace(/&#0?39;|&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(parseInt(d, 10)))
  .replace(/&amp;/g, '&');

function halifaxToday(now = new Date()) {
  return now.toLocaleDateString('en-CA', { timeZone: 'America/Halifax', year: 'numeric', month: '2-digit', day: '2-digit' });
}

// Markers the blog-polish prompt asks for, and placeholders; none may reach a published post.
const LEFTOVER = new RegExp([
  String.raw`\b(?:AT_A_GLANCE|END_AT_A_GLANCE|ANSWER_BLOCK|END_ANSWER_BLOCK|CALLOUT_BLOCK|END_CALLOUT_BLOCK|FAQ_QUESTION|FAQ_ANSWER|SEO_META|BLOG_READY)\b`,
  String.raw`\b(?:TODO|TBD|XXX+)\b`,   // upper case only: "todo" and "tbd" are ordinary words
].join('|'));
const LEFTOVER_BRACKET = /\[(?:insert|link|citation|source)\b[^\]]*\](?!\()|lorem ipsum/i;   // "[INSERT LINK]", not a link's text
const leftoverIn = text => LEFTOVER.exec(text) || LEFTOVER_BRACKET.exec(text);

function summarise(checks) {
  return {
    failures: checks.filter(c => c.status === 'fail'),
    warnings: checks.filter(c => c.status === 'warn'),
    ok: !checks.some(c => c.status === 'fail'),
  };
}

// ── Markdown (front matter) ───────────────────────────────────────────────────
const scalar = v => {
  v = String(v).trim();
  if (v.startsWith('"')) { try { return JSON.parse(v); } catch { /* fall through */ } }
  return v;
};

function parseFrontMatter(md) {
  const m = /^---\n([\s\S]*?)\n---\n?([\s\S]*)$/.exec(String(md || '').replace(/\r\n/g, '\n'));
  if (!m) return null;
  const fm = {}, tags = [], faq = [];
  let cur = null, x;
  for (const line of m[1].split('\n')) {
    if ((x = /^([a-z_]+):\s*(.*)$/.exec(line))) { cur = x[1]; if (x[2] !== '') fm[cur] = scalar(x[2]); continue; }
    if (cur === 'tags' && (x = /^\s+-\s+(.*)$/.exec(line))) tags.push(scalar(x[1]));
    else if (cur === 'faq') {
      if ((x = /^\s+-\s+q:\s*(.*)$/.exec(line))) faq.push({ q: scalar(x[1]), a: '' });
      else if ((x = /^\s+a:\s*(.*)$/.exec(line)) && faq.length) faq[faq.length - 1].a = scalar(x[1]);
    }
  }
  return { fm, tags, faq, body: m[2] };
}

function descriptionChecks(desc, label = 'Meta description') {
  const out = [];
  if (!desc) return [fail('description', label, 'Missing.', { retry: true })];
  const len = desc.length;
  if (len < DESC_MIN || len > DESC_MAX) out.push(fail('description-length', label, `${len} characters; the target is ${DESC_MIN} to ${DESC_MAX}.`, { retry: true }));
  else out.push(pass('description-length', label, `${len} characters.`));
  if (/in this post/i.test(desc)) out.push(warn('description-generic', label, 'Starts like a generic summary ("In this post"); make it specific.'));
  return out;
}

// Straight double quotes and angle brackets in a field the layout puts inside an HTML attribute.
function attributeSafety(fm) {
  const bad = ['title', 'seo_title', 'description', 'og_title', 'og_description']
    .filter(k => fm[k] && /["<>]/.test(fm[k]));
  return bad.length
    ? fail('attribute-safe', 'Quotes in meta fields', `${bad.join(', ')} contain " < or >. The layout writes these into HTML attributes without escaping, so the tag ends early and the text is cut off. Use curly quotes.`, { fixable: true })
    : pass('attribute-safe', 'Quotes in meta fields', 'No straight quotes or angle brackets in title or description fields.');
}

function bodyLinks(body) {
  const links = [];
  for (const m of body.matchAll(/\[[^\]]*\]\(([^)\s]+)\)/g)) links.push(m[1]);
  for (const m of body.matchAll(/<a\b[^>]*\bhref="([^"]+)"/gi)) links.push(m[1]);
  return links;
}
const isInternal = h => /^\/(?!\/)/.test(h) || /^https?:\/\/(www\.)?bynorthlight\.ca(\/|$)/i.test(h);

function checkMarkdown(md, { slug = '', expectedDate = null, now = new Date() } = {}) {
  const parsed = parseFrontMatter(md);
  if (!parsed) { const checks = [fail('front-matter', 'Front matter', 'The post has no readable front matter.')]; return { checks, ...summarise(checks) }; }
  const { fm, tags, faq, body } = parsed;
  const checks = [];

  if (fm.layout !== 'post') checks.push(fail('layout', 'Layout', `layout is "${fm.layout || ''}", it must be post.`));

  // Title tag
  const titlePart = fm.seo_title || fm.title || '';
  if (!titlePart) checks.push(fail('title', 'Title tag', 'No title.'));
  else if (/\|/.test(titlePart) || /northlight/i.test(titlePart)) checks.push(fail('title', 'Title tag', 'The title carries branding or a pipe; the layout already adds " — Northlight Advisory Services".'));
  else if (titlePart.length > TITLE_FAIL) checks.push(fail('title', 'Title tag', `${titlePart.length} characters before the site suffix; over ${TITLE_FAIL} is cut off in search.`));
  else if (titlePart.length > TITLE_PASS) checks.push(warn('title', 'Title tag', `${titlePart.length} characters before the " — Northlight Advisory Services" suffix (${titlePart.length + TITLE_SUFFIX.length} in all); search results may cut the end. Key words come first.`));
  else checks.push(pass('title', 'Title tag', `${titlePart.length} characters before the suffix.`));

  checks.push(...descriptionChecks(fm.description));
  checks.push(attributeSafety(fm));

  // Canonical comes from permalink
  const permalink = fm.permalink || '';
  const okPermalink = /^\/blog\/[a-z0-9-]+\.html$/.test(permalink) && (!slug || permalink === `/blog/${slug}.html`);
  checks.push(okPermalink ? pass('canonical', 'Canonical URL', permalink) : fail('canonical', 'Canonical URL', `permalink "${permalink}" is not /blog/${slug || '<slug>'}.html.`, { retry: !slug }));

  // Dates
  const today = halifaxToday(now);
  const dateRaw = String(fm.date || '');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateRaw)) checks.push(fail('date', 'Date', `date "${dateRaw}" is not YYYY-MM-DD.`, { fixable: true }));
  else if (dateRaw > today) checks.push(fail('date', 'Date', `date ${dateRaw} is in the future (today is ${today}).`, { fixable: true }));
  else if (expectedDate && /^\d{4}-\d{2}-\d{2}$/.test(expectedDate) && dateRaw !== (expectedDate > today ? today : expectedDate)) {
    checks.push(fail('date', 'Date', `date is ${dateRaw} but the card's post date is ${expectedDate}${expectedDate > today ? ` (today, ${today}, when it is in the future)` : ''}.`, { fixable: true }));
  } else checks.push(pass('date', 'Date', dateRaw));
  const pt = String(fm.published_time || '');
  if (dateRaw && pt && !pt.startsWith(dateRaw)) checks.push(fail('published-time', 'Published time', `published_time ${pt} does not match date ${dateRaw}.`, { fixable: true }));
  if (fm.date_modified && fm.date_modified < dateRaw) checks.push(fail('date-modified', 'Date modified', `date_modified ${fm.date_modified} is before date ${dateRaw}.`, { fixable: true }));

  // source_label
  checks.push(SOURCE_LABELS.includes(fm.source_label)
    ? pass('source-label', 'source_label', fm.source_label)
    : fail('source-label', 'source_label', `"${fm.source_label || ''}" is not in the locked taxonomy (${SOURCE_LABELS.join(', ')}).`));

  // Headings, FAQ
  const bodyNoHtml = body.replace(/<div[\s\S]*?<\/div>/g, '');
  const h1s = (bodyNoHtml.match(/^# .+$/gm) || []).length;
  checks.push(h1s === 0 ? pass('h1', 'H1', 'The layout writes the single H1 from the title.') : fail('h1', 'H1', `${h1s} "# " heading in the body; it would be a second H1.`));
  const questionH2 = (bodyNoHtml.match(/^##\s+.*\?\s*$/gm) || []);
  if (!questionH2.length) checks.push(na('faq', 'FAQPage schema', 'No question headings.'));
  else if (!faq.length) checks.push(fail('faq', 'FAQPage schema', `${questionH2.length} question heading(s) but no faq: block, so no FAQPage schema.`, { retry: true }));
  else if (faq.length < 3) checks.push(warn('faq', 'FAQPage schema', `${faq.length} FAQ pairs; the standard is 3 or more.`));
  else checks.push(pass('faq', 'FAQPage schema', `${faq.length} FAQ pairs.`));
  if (faq.some(f => !f.q || !f.a)) checks.push(fail('faq-pairs', 'FAQ pairs', 'A FAQ question or answer is empty.', { retry: true }));

  // Links and images
  const internal = bodyLinks(body).filter(isInternal);
  checks.push(internal.length >= 2 ? pass('internal-links', 'Internal links', `${internal.length} in the body.`) : fail('internal-links', 'Internal links', `${internal.length} internal link(s) in the body; at least 2 are required.`));
  const emptyAlt = (body.match(/!\[\s*\]\(/g) || []).length + (body.match(/<img\b(?![^>]*\balt=)[^>]*>/gi) || []).length
    + (body.match(/<img\b[^>]*\balt=""[^>]*>/gi) || []).filter(t => !/role="presentation"|aria-hidden/i.test(t)).length;
  checks.push(emptyAlt ? fail('alt-text', 'Image alt text', `${emptyAlt} image(s) without alt text.`) : pass('alt-text', 'Image alt text', 'No images without alt text.'));

  // Leftovers
  const left = leftoverIn(body + '\n' + faq.map(f => f.q + ' ' + f.a).join('\n'));
  checks.push(left ? fail('leftover', 'Placeholders', `Found "${left[0]}" in the post; it is a pipeline marker or a placeholder.`, { retry: true }) : pass('leftover', 'Placeholders', 'None.'));

  // Standing link rules
  const plain = body.replace(/\[[^\]]*\]\([^)]*\)(\{:[^}]*\})?/g, '').replace(/<a\b[^>]*>[\s\S]*?<\/a>/gi, '').replace(/^#{1,6}\s.*$/gm, '').replace(/https?:\/\/\S+/g, '');
  const unlinked = [/\bPIPEDA\b/.test(plain) && 'PIPEDA', /\bCLOUD Act\b/.test(plain) && 'CLOUD Act'].filter(Boolean);
  if (unlinked.length) checks.push(warn('standing-links', 'PIPEDA / CLOUD Act links', `${unlinked.join(' and ')} mentioned without a link in the body.`));

  if (!tags.length) checks.push(warn('tags', 'Tags', 'No tags, so the post has no sidebar filters and no related reading.'));

  return { checks, ...summarise(checks) };
}

// ── Live HTML ─────────────────────────────────────────────────────────────────
function tagAttrs(tag) {
  const o = {};
  tag.replace(/([\w:-]+)\s*=\s*"([^"]*)"/g, (m, k, v) => { o[k.toLowerCase()] = decode(v); return m; });
  return o;
}

function checkHtml(html, { slug = '', url = '', expectedDate = null } = {}) {
  html = String(html || '');
  const canonicalExpected = url || (slug ? `${SITE}/blog/${slug}.html` : '');
  const checks = [];
  const metas = [...html.matchAll(/<meta\b[^>]*>/gi)].map(m => tagAttrs(m[0]));
  const meta = (key, val) => metas.find(a => a[key] === val)?.content;
  const prop = p => meta('property', p);
  const name = n => meta('name', n);

  // Title
  const titleRaw = decode((/<title>([\s\S]*?)<\/title>/i.exec(html) || [])[1] || '').trim();
  if (!titleRaw) checks.push(fail('title', 'Title tag', 'No <title>.'));
  else if (!titleRaw.endsWith(TITLE_SUFFIX) || titleRaw.split(SITE_NAME).length !== 2 || /\|/.test(titleRaw)) checks.push(fail('title', 'Title tag', `"${titleRaw}" does not end with exactly one "${TITLE_SUFFIX.trim()}" (no pipe, no double branding).`));
  else {
    const part = titleRaw.slice(0, -TITLE_SUFFIX.length);
    checks.push(part.length > TITLE_FAIL ? fail('title', 'Title tag', `${part.length} characters before the suffix.`)
      : part.length > TITLE_PASS ? warn('title', 'Title tag', `${part.length} characters before the suffix (${titleRaw.length} in all); the end may be cut in search.`)
      : pass('title', 'Title tag', `${titleRaw.length} characters in all.`));
  }

  // JSON-LD
  const ld = [];
  let ldBad = 0;
  for (const m of html.matchAll(/<script\b[^>]*type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/gi)) {
    try { ld.push(JSON.parse(m[1])); } catch { ldBad++; }
  }
  const ofType = t => ld.find(o => o && (o['@type'] === t || (Array.isArray(o['@type']) && o['@type'].includes(t))));
  const article = ofType('Article') || ofType('BlogPosting');

  // Description, and that the meta tags were not cut off (the unescaped quote bug)
  const desc = name('description');
  checks.push(...descriptionChecks(desc));
  const ogDesc = prop('og:description'), twDesc = name('twitter:description');
  const fullDesc = article?.description;
  // The meta description must equal the schema's; og/twitter may be set differently on purpose, but not be a cut-off of either.
  const cut = fullDesc ? [['meta description', desc], ['og:description', ogDesc], ['twitter:description', twDesc]]
    .filter(([n, v]) => v != null && v !== fullDesc && (n === 'meta description' || (v !== desc && (fullDesc.startsWith(v) || (desc || '').startsWith(v))))) : [];
  checks.push(cut.length && fullDesc
    ? fail('attribute-cut', 'Meta tags cut off', `${cut.map(([n, v]) => `${n} is "${v}" (${v.length} characters)`).join('; ')}, but the Article schema has ${fullDesc.length} characters. A straight " in the source ended the attribute early.`, { fixable: true })
    : pass('attribute-cut', 'Meta tags cut off', 'Meta, Open Graph, Twitter and schema descriptions agree.'));

  checks.push(name('author') === AUTHOR ? pass('author', 'Author tag', AUTHOR) : fail('author', 'Author tag', `author is "${name('author') || 'missing'}", expected "${AUTHOR}".`));

  const canonical = (/<link\b[^>]*rel="canonical"[^>]*>/i.exec(html) ? tagAttrs(/<link\b[^>]*rel="canonical"[^>]*>/i.exec(html)[0]).href : '') || '';
  if (!canonical) checks.push(fail('canonical', 'Canonical URL', 'Missing.'));
  else if (/\/$/.test(canonical) || (canonicalExpected && canonical !== canonicalExpected)) checks.push(fail('canonical', 'Canonical URL', `${canonical}${canonicalExpected ? ` is not ${canonicalExpected}` : ' has a trailing slash'}.`));
  else checks.push(pass('canonical', 'Canonical URL', canonical));

  // Open Graph
  const og = [];
  const ogEq = (p, want) => { if (prop(p) !== want) og.push(`${p} is "${prop(p) ?? 'missing'}", expected "${want}"`); };
  ogEq('og:type', 'article'); ogEq('og:site_name', SITE_NAME); ogEq('og:image', OG_IMAGE);
  ogEq('og:image:width', '1200'); ogEq('og:image:height', '630'); ogEq('article:author', AUTHOR);
  if (!prop('og:title')) og.push('og:title missing');
  if (!ogDesc) og.push('og:description missing');
  if (canonical && prop('og:url') !== canonical) og.push(`og:url is "${prop('og:url') ?? 'missing'}", not the canonical`);
  const pub = prop('article:published_time');
  if (!pub || !/^\d{4}-\d{2}-\d{2}T[\d:.]+Z?$/.test(pub)) og.push(`article:published_time "${pub ?? 'missing'}" is not ISO 8601`);
  checks.push(og.length ? fail('open-graph', 'Open Graph', og.join('; ') + '.') : pass('open-graph', 'Open Graph', 'All required tags present.'));

  const tw = [];
  if (name('twitter:card') !== 'summary_large_image') tw.push(`twitter:card is "${name('twitter:card') ?? 'missing'}"`);
  for (const k of ['twitter:title', 'twitter:description']) if (!name(k)) tw.push(`${k} missing`);
  if (name('twitter:image') !== OG_IMAGE) tw.push(`twitter:image is "${name('twitter:image') ?? 'missing'}"`);
  if (prop('og:title') && name('twitter:title') && prop('og:title') !== name('twitter:title')) tw.push('twitter:title differs from og:title (cut off?)');
  checks.push(tw.length ? fail('twitter', 'Twitter card', tw.join('; ') + '.') : pass('twitter', 'Twitter card', 'All required tags present.'));

  // Schema
  if (ldBad) checks.push(fail('json-ld', 'JSON-LD', `${ldBad} schema block(s) are not valid JSON.`));
  if (!article) checks.push(fail('article-schema', 'Article schema', 'No Article schema.'));
  else {
    const p = [];
    if (!article.headline) p.push('headline missing');
    if (!/^\d{4}-\d{2}-\d{2}$/.test(article.datePublished || '')) p.push(`datePublished "${article.datePublished ?? 'missing'}" is not YYYY-MM-DD`);
    if (!article.dateModified) p.push('dateModified missing');
    if (article.image !== OG_IMAGE) p.push(`image is "${article.image ?? 'missing'}"`);
    const au = article.author || {};
    if (au['@type'] !== 'Person' || au.name !== AUTHOR || au.url !== AUTHOR_URL) p.push(`author is ${JSON.stringify(au)}, expected Person "${AUTHOR}" ${AUTHOR_URL}`);
    const pu = article.publisher || {};
    if (pu['@type'] !== 'Organization' || pu.name !== SITE_NAME || pu.url !== SITE) p.push(`publisher is ${JSON.stringify(pu)}, expected Organization "${SITE_NAME}" ${SITE}`);
    if (canonical && article.url !== canonical) p.push(`url "${article.url ?? 'missing'}" is not the canonical`);
    checks.push(p.length ? fail('article-schema', 'Article schema', p.join('; ') + '.') : pass('article-schema', 'Article schema', 'Complete.'));
  }
  const bc = ofType('BreadcrumbList');
  const items = bc?.itemListElement || [];
  checks.push(bc && items.length === 3 && items[0].name === 'Home' && items[1].name === 'Blog' && items[2].name
    ? pass('breadcrumb', 'BreadcrumbList schema', 'Home → Blog → post.') : fail('breadcrumb', 'BreadcrumbList schema', 'Expected three items: Home, Blog, the post.'));

  // Body
  const bodyStart = html.search(/<div class="post-body"/i);
  const rest = bodyStart === -1 ? html : html.slice(bodyStart);
  const endRel = rest.search(/<section class="faq-section"|<div class="related-reading"|<\/article>/i);
  const bodyHtml = endRel === -1 ? rest : rest.slice(0, endRel);

  const h1 = (html.match(/<h1\b/gi) || []).length;
  checks.push(h1 === 1 ? pass('h1', 'H1', 'Exactly one.') : fail('h1', 'H1', `${h1} <h1> elements, expected exactly one.`));

  const questionH2 = [...bodyHtml.matchAll(/<h2\b[^>]*>([\s\S]*?)<\/h2>/gi)].map(m => m[1].replace(/<[^>]+>/g, '').trim()).filter(t => /\?$/.test(t));
  const faqLd = ofType('FAQPage');
  if (!questionH2.length) checks.push(na('faq', 'FAQPage schema', 'No question headings.'));
  else if (!faqLd || !(faqLd.mainEntity || []).length) checks.push(fail('faq', 'FAQPage schema', `${questionH2.length} question heading(s) but no FAQPage schema.`));
  else if ((faqLd.mainEntity || []).some(q => !q.name || !q.acceptedAnswer?.text)) checks.push(fail('faq', 'FAQPage schema', 'A Question has no name or answer text.'));
  else checks.push(pass('faq', 'FAQPage schema', `${faqLd.mainEntity.length} Question/Answer pairs.`));

  const hrefs = [...bodyHtml.matchAll(/<a\b([^>]*)>/gi)].map(m => tagAttrs(`<a ${m[1]}>`));
  const internal = hrefs.filter(a => a.href && isInternal(a.href));
  const blank = internal.filter(a => a.target === '_blank').length;
  checks.push(internal.length < 2 ? fail('internal-links', 'Internal links', `${internal.length} internal link(s) in the post body; at least 2 are required.`)
    : blank ? fail('internal-links', 'Internal links', `${blank} internal link(s) open in a new tab.`)
    : pass('internal-links', 'Internal links', `${internal.length} in the post body.`));

  const imgs = [...html.matchAll(/<img\b[^>]*>/gi)].map(m => tagAttrs(m[0]));
  const badImg = imgs.filter(a => a.alt === undefined || (a.alt === '' && a.role !== 'presentation' && a['aria-hidden'] !== 'true'));
  checks.push(badImg.length ? fail('alt-text', 'Image alt text', `${badImg.length} image(s) with missing or empty alt: ${badImg.map(a => a.src).join(', ')}.`) : pass('alt-text', 'Image alt text', `${imgs.length} image(s), all described or decorative.`));

  // Dates agree everywhere
  const timeTag = /<time\b[^>]*datetime="([^"]+)"/i.exec(html)?.[1];
  const dates = { 'article:published_time': pub ? pub.slice(0, 10) : null, datePublished: article?.datePublished || null, '<time>': timeTag || null };
  const distinct = [...new Set(Object.values(dates).filter(Boolean))];
  if (expectedDate && article?.datePublished && article.datePublished !== expectedDate) {
    checks.push(fail('dates-expected', 'Date matches the card', `The page says ${article.datePublished} but the card's post date is ${expectedDate}.`, { fixable: true }));
  }
  checks.push(distinct.length > 1 ? fail('dates', 'Dates agree', `Dates differ: ${Object.entries(dates).map(([k, v]) => `${k}=${v}`).join(', ')}.`) : pass('dates', 'Dates agree', distinct[0] || 'none found'));

  const visible = bodyHtml.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, '').replace(/<[^>]+>/g, ' ');
  const left = leftoverIn(visible);
  checks.push(left ? fail('leftover', 'Placeholders', `Found "${left[0]}" in the visible text.`) : pass('leftover', 'Placeholders', 'None.'));

  return { checks, ...summarise(checks) };
}

// ── Polish output against polish input ────────────────────────────────────────
const plainText = s => String(s || '')
  .replace(/\[([^\]]+)\]\([^)]*\)(\{:[^}]*\})?/g, '$1').replace(/<[^>]+>/g, '')
  .replace(/\*\*(.+?)\*\*/g, '$1').replace(/\*(.+?)\*/g, '$1').replace(/_(.+?)_/g, '$1')
  .replace(/^\s*>\s?/gm, '').replace(/^\s*(?:[-*]|\d+\.)\s+/gm, '');

function sentencesOf(text) {
  return plainText(text).split(/\n+/).flatMap(p => p.split(/(?<=[.!?…])["”’)]*\s+(?=["“‘(\[]?[A-Z0-9])/))
    .map(s => s.replace(/\s+/g, ' ').trim()).filter(s => s.split(' ').length >= 3);
}

// The parts of blog polish output that are new by design: the summary box, answer blocks, FAQ, headings.
function stripGeneratedStructure(text) {
  let t = String(text || '').replace(/\r\n/g, '\n');
  const faq = t.search(/^[ \t]*FAQ_QUESTION[ \t]*$/m);
  if (faq !== -1) t = t.slice(0, faq);
  t = t.replace(/^[ \t]*AT_A_GLANCE[ \t]*\n[\s\S]*?\n[ \t]*END_AT_A_GLANCE[ \t]*$/gm, '')
       .replace(/^[ \t]*ANSWER_BLOCK[ \t]*\n[\s\S]*?\n[ \t]*END_ANSWER_BLOCK[ \t]*$/gm, '')
       .replace(/^[ \t]*(CALLOUT_BLOCK|END_CALLOUT_BLOCK)[ \t]*$/gm, '')
       .replace(/^#{1,6}\s.*$/gm, '');
  return t;
}

const tokens = s => s.toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').split(/\s+/).filter(Boolean);
function similarity(a, b) {
  const A = new Set(a), B = new Set(b);
  if (!A.size || !B.size) return 0;
  let inter = 0; for (const t of A) if (B.has(t)) inter++;
  return inter / Math.max(A.size, B.size);   // 1 only when the word sets match
}

// Returns { added, reworded, dropped } as lists of sentences. added = nothing in the input is close;
// reworded = close but not the same; dropped = in the input, nowhere in the output.
function diffPolish(input, output, { sameAt = 0.92, rewordedAt = 0.6 } = {}) {
  const inS  = sentencesOf(stripGeneratedStructure(input));
  const outS = sentencesOf(stripGeneratedStructure(output));
  const inT  = inS.map(tokens);
  const matchedIn = new Set();
  const added = [], reworded = [];
  for (const s of outS) {
    const t = tokens(s);
    let best = 0, bi = -1;
    inT.forEach((u, i) => { const v = similarity(t, u); if (v > best) { best = v; bi = i; } });
    if (best >= sameAt) { matchedIn.add(bi); continue; }
    if (best >= rewordedAt) { matchedIn.add(bi); reworded.push({ output: s, input: inS[bi] }); continue; }
    added.push(s);
  }
  const dropped = inS.filter((_, i) => !matchedIn.has(i));
  const checks = [
    added.length ? fail('added-sentences', 'Sentences added by polish', `${added.length} sentence(s) are not in the approved draft: ${added.map(s => `"${s}"`).join(' | ')}`, { retry: true, sentences: added })
      : pass('added-sentences', 'Sentences added by polish', 'None.'),
    reworded.length ? warn('reworded-sentences', 'Sentences reworded by polish', `${reworded.length} sentence(s) changed: ${reworded.map(r => `"${r.input}" → "${r.output}"`).join(' | ')}`)
      : pass('reworded-sentences', 'Sentences reworded by polish', 'None.'),
    dropped.length > 3 ? warn('dropped-sentences', 'Sentences dropped by polish', `${dropped.length} sentence(s) from the draft are gone: ${dropped.slice(0, 5).map(s => `"${s}"`).join(' | ')}`)
      : pass('dropped-sentences', 'Sentences dropped by polish', `${dropped.length}.`),
  ];
  return { added, reworded, dropped, checks, ...summarise(checks) };
}

// Text report in the same shape as the /blog-pre-publish table.
function formatChecks(checks) {
  const icon = { pass: '✅', fail: '❌', warn: '⚠️', na: '—' };
  return checks.map(c => `${icon[c.status]} ${c.label}${c.note ? `: ${c.note}` : ''}`).join('\n');
}

module.exports = {
  SITE, SITE_NAME, TITLE_SUFFIX, SOURCE_LABELS, DESC_MIN, DESC_MAX,
  parseFrontMatter, checkMarkdown, checkHtml, diffPolish, sentencesOf, stripGeneratedStructure, formatChecks, halifaxToday,
};
